mapper.delete:
UPDATE mdm_material_version
SET deleted = DATE_FORMAT(NOW(6), '%Y%m%d%H%i%s%m'), version = version + 1
WHERE deleted = 0
    AND material_code = #{materialCode}
    AND tenant_code = #{tenantCode}
    AND version_no NOT IN (
        SELECT v.version_no FROM (
            SELECT version_no FROM mdm_material_version
            WHERE deleted = 0 AND material_code = #{materialCode}
            AND tenant_code = #{tenantCode}
            ORDER BY version_no DESC LIMIT #{keepCount}
        ) v
    )
